import { QUESTIONS_ACTIONS } from './actions'

export const INITIAL_STATE = {
  requiredQuestionMap: {}
}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case QUESTIONS_ACTIONS.GET_QUESTION_STEPS:
    case QUESTIONS_ACTIONS.GET_QUESTION:
    case QUESTIONS_ACTIONS.SUBMIT_ANSWER:
      return {
        ...state,
        ...payload
      }
    case QUESTIONS_ACTIONS.UPDATE_REQUIRED_QUESTIONS:
      return {
        requiredQuestionMap: {
          ...payload
        }
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
