import { useEffect, useState } from 'react'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { Fill, RadioBox, RadioInput } from '../../../../../components/Radio/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { HorizontalRadioStyle } from './index.style'

function HorizontalRadioQuestion (props) {
  const {
    title, onRadioSelect, selectedData = {}, data = [],
    className, titleSize, titleColor, titleWeight, id,
    defaultValue = {}
  } = props

  const [selected, setSelected] = useState(defaultValue.value)

  useEffect(() => {
    if (defaultValue.value && !selected) {
      onRadioSelect(defaultValue.value)
    }
  }, [onRadioSelect, defaultValue, selected])

  const handleRadioChange = (select) => {
    setSelected(select)
    onRadioSelect(select)
  }

  return (
    <HorizontalRadioStyle className={`checkbox-extra-data ${className}`} id={id}>
      {
        title && (
          <CustomText
            color={titleColor || AgentColorPallette.fontDarkerGrey}
            size={titleSize || '10px'}
            weight={titleWeight || 'normal'}
            bottom='4px'
          >
            {title}
          </CustomText>
        )
      }
      <Row align='center' justify='space-between' className='radio-box-container'>
        {
          data && data.map((item, index) => (
            <DisplayFlexCCC key={`radio-box-${id}-${index}`}>
              <CustomText
                color={AgentColorPallette.black}
                bottom='4px'
              >
                {item.title}
              </CustomText>
              <RadioBox
                key={`horizontal-radio-box-${id}-${index}`}
                onClick={() => handleRadioChange(item.title)}
              >
                <RadioInput
                  value={item.title}
                  name={`${id}-${item.title}`}
                  aria-checked={(item.title === selected) || (item.title === selectedData.scale)}
                  checked={(item.title === selected) || (item.title === selectedData.scale)}
                />
                <Fill />
              </RadioBox>
            </DisplayFlexCCC>
          ))
        }
      </Row>
    </HorizontalRadioStyle>
  )
}

export default HorizontalRadioQuestion
