import { useState, useCallback, useMemo } from 'react'
import { CustomText, InnerInput } from '../../../../../components'
import VerticalRadioGroup from '../../../../../components/VerticalRadioGroup'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import QuestionTitle from '../QuestionTitle'
import { RadioQuestionStyle } from './index.style'

function RadioQuestion (props) {
  const {
    title, data = [], onDataSelect, id,
    defaultValue, required
  } = props
  // using useMemo to set the selected value on basis of default value
  const othersId = useMemo(() => `lainnya${id}`, [id])
  const preSelectValue = useMemo(() => {
    return defaultValue ? data.find(item => item.title === defaultValue) ? `${defaultValue}`.replace(/\s/g, '') : 'Lainnya...' : undefined
  }, [data, defaultValue])
  const [selected, setSelected] = useState(preSelectValue)

  const handleSelectedRadio = useCallback((selectedOption) => {
    if (selectedOption.id !== othersId) {
      setSelected(selectedOption.id)
      onDataSelect({
        [id]: {
          value: selectedOption.title
        }
      })
    } else {
      // this is the title of others so we have put this as selected item
      setSelected('Lainnya...')
      onDataSelect({
        [id]: { value: '' }
      })
    }
  }, [onDataSelect, id, othersId])

  const handleInputChange = useCallback((value) => {
    onDataSelect({
      [id]: { value }
    })
  }, [onDataSelect, id])

  return (
    <RadioQuestionStyle>
      <QuestionTitle title={title} required={required} />
      {
        data.map(option => {
          const modifiedOption = {
            ...option,
            id: (option.title !== 'Lainnya...') ? option.title.replace(/\s/g, '') : othersId
          }
          return (
            <VerticalRadioGroup
              key={option.title}
              data={modifiedOption}
              selected={selected !== 'Lainnya...' ? selected : othersId}
              align='start'
              label={
                <div className='radio-box-que-container'>
                  <CustomText
                    color={AgentColorPallette.black}
                    onClick={() => handleSelectedRadio(modifiedOption)}
                  >
                    {option.title}
                  </CustomText>
                  {
                    (selected === 'Lainnya...' && selected === option.title) && (
                      <InnerInput
                        name={`${option.title}${id}`}
                        className='question-input-text'
                        placeholder='Masukan here'
                        displayBorder
                        defaultValue={preSelectValue === 'Lainnya...' ? defaultValue : ''}
                        onChange={(e) => handleInputChange(e.target.value, modifiedOption)}
                      />
                    )
                  }
                </div>
              }
              name={modifiedOption.id}
              className='radio-question'
              onChange={handleSelectedRadio}
              levelRightPosition
            />
          )
        })
      }
    </RadioQuestionStyle>
  )
}

export default RadioQuestion
