import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useSelectCityContextValue } from '../../context'
import { getCitiesRequest } from '../actions'

export const useGetCitiesData = () => {
  const [selectCitesState, dispatch] = useSelectCityContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(getCitiesRequest({
      ...payload
    }))
  }
  return [selectCitesState, request]
}
