import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { BottomBtnStyle } from './index.style'

function BottomBtn (props) {
  const {
    showPrev, completedLinePercent, onNextClick,
    disabledNext, backBtnId, nextBtnId, nextBtnText
  } = props

  const handleBtn = (type) => {
    if (type === 'next') {
      onNextClick(type)
    } else {
      window.history.back()
    }
  }

  return (
    <BottomBtnStyle padding='0' justify='space-between' linePercent={completedLinePercent}>
      <Row justify='space-between' className='action-inner-box' align='center'>
        <CustomText
          id={backBtnId}
          className='btn-text'
          textAlign='center'
          color={AgentColorPallette.uiGold}
          weight={700}
          onClick={() => handleBtn('prev')}
        >
          {showPrev && LANG_STRINGS.previousNew}
        </CustomText>
        <div className='steps-complete-line'>
          {!!completedLinePercent && <div className='steps-completed' />}
        </div>
        <CustomText
          className='btn-text'
          id={!disabledNext ? nextBtnId : undefined}
          textAlign='center'
          color={disabledNext ? AgentColorPallette.fontSecondary : AgentColorPallette.uiGold}
          weight={700}
          onClick={() => disabledNext ? null : handleBtn('next')}
        >
          {nextBtnText}
        </CustomText>
      </Row>
    </BottomBtnStyle>
  )
}

export default BottomBtn
