import { createContext, useContext, useReducer } from 'react'
import reducers, { INITIAL_STATE } from '../state/reducers'

export const SelectCityContext = createContext()

export const SelectCityContextProvider = (props) => {
  return (
    <SelectCityContext.Provider value={useReducer(reducers, INITIAL_STATE)}>
      {props.children}
    </SelectCityContext.Provider>
  )
}

export const useSelectCityContextValue = () => useContext(SelectCityContext)
