import { SELECT_CITY_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducers = (state = INITIAL_STATE, action = {}) => {
  const { type, payload } = action
  switch (type) {
    case SELECT_CITY_ACTIONS.GET_CITIES:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducers
