import { Fragment, useCallback, useEffect, useRef, useState } from 'react'
import { Container, InnerInput } from '../../../../components'
import SelectCityModal from '../../../../components/SelectCityModal'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { ERROR_LANG, LANG_STRINGS } from '../../../../lang'
import BooleanQuestion from '../components/BooleanQuestion'
import QuestionSteps from '../components/QuestionSteps'
import { useGetQuestions, useGetQuestionsSteps, useSubmitAnswers } from '../state/hooks/useQuestionnaireState'
import { QuestionContainerStyle } from './index.style'
import BottomBtn from '../components/BottomBtn'
import { getPercentageCal } from '../helpers'
import RadioQuestion from '../components/RadioQuestion'
import ShowSnackbar from '../../../../components/ShowNotification'
import EmptyList from '../../../../components/EmptyList'
import QuestionTitle from '../components/QuestionTitle'
import { find } from 'lodash/collection'
import { setToLocalStorage } from '../../../../helpers/localstorage'
import { SHOW_QUESTIONNAIRE_SUBMIT_MSG } from '../../../../constants/cookies'
import get from 'lodash/get'
import isEmpty from 'lodash/isEmpty'

function QuestionsContainer (props) {
  const { history, match } = props
  const [showBarMap, setShowBarMap] = useState({})
  const [{
    GET_QUESTION_STEPS_LOADER, GET_QUESTION_LOADER, SUBMIT_ANSWER_LOADER,
    GET_CITIES_LOADER
  }] = useLoaderContextValue()
  const [
    {
      GET_QUESTION_STEPS_ERROR, getQuestionsStepsStatus,
      SUBMIT_ANSWER_ERROR, submitAnswerStatus,
      GET_QUESTION_ERROR
    },
    dispatchError
  ] = useErrorContextValue()
  const [{ getQuestionStepsData = [] }, getQuestionStepsRequest] = useGetQuestionsSteps()
  const [{ getQuestionData = {} }, getQuestionRequest] = useGetQuestions()
  const [, submitAnswers] = useSubmitAnswers()
  const [isNextEnable, setIsNextEnable] = useState(false)

  const initializeThat = useCallback(() => {
    return {
      initialCompletedPercent: 33.333333333333333 * (parseInt(match.params.step) - 1),
      step: parseInt(match.params.step),
      answers: {},
      requiredQuestionMap: {},
      currentUrl: match.url
    }
  }, [match])

  // initialize that to access the initial data
  const that = useRef(initializeThat())
  // if the steps is completed then on basis of the steps we are showing
  // previous filled
  const [completedPercent, setCompletedPercent] = useState(that.current.initialCompletedPercent)
  const [showPrev, setShowPrev] = useState(!!completedPercent)

  useEffect(() => {
    if (GET_QUESTION_STEPS_LOADER === undefined) {
      getQuestionStepsRequest()
    }
    if (GET_QUESTION_LOADER === undefined) {
      getQuestionRequest({
        step: that.current.step
      })
    }

    // if the use comes back or using the upper routes navigator
    // than handle the component re-render
    if (that.current.currentUrl !== match.url) {
      getQuestionStepsRequest()
      that.current = {
        ...initializeThat()
      }
      setCompletedPercent(that.current.initialCompletedPercent)
      getQuestionRequest({
        step: that.current.step
      })
    }
  }, [
    getQuestionStepsRequest, getQuestionRequest,
    GET_QUESTION_STEPS_LOADER, GET_QUESTION_LOADER,
    match, initializeThat
  ])

  const updateSnackBar = useCallback((text, error) => {
    setShowBarMap({
      error,
      show: true,
      msg: text
    })
    setTimeout(() => {
      setShowBarMap({
        show: false
      })
    }, 3000)
  }, [])

  useEffect(() => {
    if (submitAnswerStatus === 'success') {
      // here we check if the data submitted on last step
      // if yes then we move the user to last step
      if (that.current.step === getQuestionStepsData.length) {
        // if all questions answers that means now the final step so move the
        // agent to dashboard
        setToLocalStorage(SHOW_QUESTIONNAIRE_SUBMIT_MSG, true)
        history.replace({
          pathname: '/dashboard'
        })
        return
      }
      that.current.step = that.current.step + 1
      updateSnackBar(LANG_STRINGS.congratsOnSuccessfulSubmission)
      dispatchError(resetError({
        submitAnswerStatus: '',
        SUBMIT_ANSWER_ERROR: false
      }))

      history.push({
        pathname: `/review/${that.current.step}/questions`
      })
      setShowPrev(that.current.step > 1)
      // getQuestionStepsRequest()
      // getQuestionRequest({
      //   step: that.current.step
      // })
    } else if (SUBMIT_ANSWER_ERROR && submitAnswerStatus) {
      updateSnackBar(submitAnswerStatus, true)
      dispatchError(resetError({
        submitAnswerStatus: '',
        SUBMIT_ANSWER_ERROR: false
      }))
    }

    if (GET_QUESTION_STEPS_ERROR && getQuestionsStepsStatus) {
      updateSnackBar(getQuestionsStepsStatus, true)
      dispatchError(resetError({
        getQuestionsStepsStatus: ''
      }))
    }
  }, [
    submitAnswerStatus, SUBMIT_ANSWER_ERROR, history,
    GET_QUESTION_STEPS_ERROR, getQuestionsStepsStatus, getQuestionStepsData.length,
    getQuestionRequest, getQuestionStepsRequest, dispatchError,
    updateSnackBar
  ])

  const updateThePercentage = useCallback((current = {}) => {
    // this function used to update the filled questions percentage
    const completedQues = Object.keys(current.answers).length
    const totalQues = getQuestionData.questions && getQuestionData.questions.length
    // need to check in required array
    that.current.isNextEnable = true
    for (const key in that.current.requiredQuestionMap) {
      that.current.isNextEnable = that.current.isNextEnable && !!current.answers[key]
    }
    setIsNextEnable(that.current.isNextEnable)
    const percent = getPercentageCal(totalQues, completedQues, 33.333333333333333)
    setCompletedPercent(
      current.initialCompletedPercent + percent
    )
  }, [getQuestionData.questions])

  const updateNestedQuestionsAns = useCallback((question) => {
    let answersMap = {}
    if (question.question_option && question.question_option.options.length) {
      const questionsPart = find(question.question_option.options, { title: question.answer.value }) || {}
      if (questionsPart.questions && questionsPart.questions.length) {
        for (const nestQuestion of questionsPart.questions) {
          if (nestQuestion.answer) {
            answersMap = {
              ...answersMap,
              [nestQuestion.id]: {
                ...nestQuestion.answer
              }
            }

            if (nestQuestion.question_option && nestQuestion.question_option.options.length) {
              if (nestQuestion.answer.value) {
                const nestedAnsMaps = updateNestedQuestionsAns(nestQuestion)
                answersMap = {
                  ...answersMap,
                  ...nestedAnsMaps
                }
              } else if (nestQuestion.answer.checked_value) {
                // if the nested elements have checked value then select only those options
                for (const key in nestQuestion.answer.checked_value) {
                  // here we are getting this values and check for the status
                  // of those rules inside the state
                  const nestedAnsMaps = updateNestedQuestionsAns({
                    ...nestQuestion,
                    answer: {
                      value: key
                    }
                  })
                  answersMap = {
                    ...answersMap,
                    ...nestedAnsMaps
                  }
                }
              }
            }
          }
        }
      }
    }

    return answersMap
  }, [])

  const updateAnswers = useCallback(() => {
    // here we are updating the data on local store
    if (getQuestionData.questions) {
      for (const question of getQuestionData.questions) {
        if (question.answer) {
          that.current.answers = {
            ...(that.current.answers || {}),
            [question.id]: {
              ...(question.answer || {})
            }
          }
          if (question.question_option && question.question_option.options.length) {
            // handle the nested questions answers so we used to create a function for that
            const nestedAnsMaps = updateNestedQuestionsAns(question)
            if (Object.keys(nestedAnsMaps).length) {
              that.current.answers[question.id] = {
                multiple_value: {
                  [question.id]: {
                    ...that.current.answers[question.id]
                  },
                  ...nestedAnsMaps
                }
              }
            }
          }
        }
      }
      if (that.current.answers) {
        updateThePercentage(that.current)
      }
    }
  }, [getQuestionData.questions, updateThePercentage, updateNestedQuestionsAns])

  useEffect(() => {
    // this effect called to setup the answers to the questions
    if (getQuestionData.questions) {
      updateAnswers()
    }
  }, [getQuestionData.questions, updateAnswers])

  const handleDataSelect = useCallback((data = {}) => {
    // this function used to collect the data from all nested elements
    const { current = {} } = that
    // always single key is coming so read the 0 index
    const dataKey = Object.keys(data)[0]
    if (data[dataKey].value || data[dataKey].multiple_value) {
      that.current.answers = {
        ...(current.answers || {}),
        ...(data)
      }
    } else {
      delete that.current.answers[dataKey]
    }
    updateThePercentage(that.current)
  }, [updateThePercentage])

  const handleInputChange = useCallback((value, selectedQue) => {
    if (value) {
      handleDataSelect({
        [selectedQue.id]: { value }
      })
    } else {
      // update the content percentage too
      delete that.current.answers[selectedQue.id]
      updateThePercentage(that.current)
    }
  }, [handleDataSelect, updateThePercentage])

  const validateSubmitData = useCallback((submittedAnswers = {}, questionsData = []) => {
    let isValid = true
    for (const question of questionsData) {
      if (question.is_required) {
        if (get(submittedAnswers, `[${question.id}].value`, false)) {
          isValid = isValid && question.is_required && !!get(submittedAnswers, `[${question.id}].value`, false)
          // now validate the other sub data of the submitted answer
          if (question.question_option && isValid) {
            const questionOptions = find(question.question_option.options, { title: submittedAnswers[question.id].value }) || {}
            if (questionOptions.questions && questionOptions.questions.length) {
              isValid = isValid && validateSubmitData(submittedAnswers, questionOptions.questions)
            }
          }
        } else if (!isEmpty(get(submittedAnswers, `[${question.id}].checked_value`, {}))) {
          const checkedValues = get(submittedAnswers, `[${question.id}].checked_value`, {})
          if (question.question_option && isValid) {
            for (const key in checkedValues) {
              if (key === 'Lainnya...' && (!checkedValues[key] || typeof (checkedValues[key]) === 'boolean')) {
                isValid = false
                break
              }
              const childQuestionOptions = find(question.question_option.options, { title: key }) || {}
              if (childQuestionOptions.questions && childQuestionOptions.questions.length) {
                isValid = isValid && validateSubmitData(submittedAnswers, childQuestionOptions.questions)
              }
            }
          }
        } else {
          isValid = false
        }

        if (!isValid) break
      }
    }
    return isValid
  }, [])

  const handleNextClick = () => {
    // submit the answers after next click
    const { answers } = that.current
    let answer = {}
    for (const key in answers) {
      // here we are going to handle the data
      if (answers[key].multiple_value) {
        answer = {
          ...answer,
          ...answers[key].multiple_value
        }
      } else {
        answer[key] = {
          ...answers[key]
        }
      }
    }
    if (validateSubmitData(answer, getQuestionData.questions)) {
      submitAnswers({
        body: {
          answer,
          step_id: that.current.step
        }
      })
      return
    }
    updateSnackBar(ERROR_LANG.pleaseProvideYourAnswer, true)
  }

  const questionBlock = useCallback((question = {}) => {
    switch (question.question_type) {
      case 'TYPE_AUTO_SEARCH':
        return (
          <SelectCityModal
            key={`auto-search-${question.id}`}
            onDataSelect={(value) => handleDataSelect({
              [question.id]: { value }
            })}
            defaultValue={question.answer && question.answer.value}
            title={LANG_STRINGS.selectCityInWhichYouOfferInsurance}
          />
        )
      case 'TYPE_BOOLEAN':
        return (
          <BooleanQuestion
            key={`type-boolean-${question.id}`}
            title={question.question}
            data={question}
            preData={that.current.answers}
            required={question.is_required}
            defaultValue={question.answer && question.answer.value}
            onDataSelect={handleDataSelect}
          />
        )
      case 'TYPE_TEXT':
        return (
          <div key={`type-text-${question.id}`}>
            <QuestionTitle title={question.question} required={question.is_required} />
            <InnerInput
              name={`question_${question.id}`}
              className='question-input-text'
              placeholder='Masukan here'
              displayBorder
              defaultValue={question.answer && question.answer.value}
              onChange={(e) => handleInputChange(e.target.value, question)}
            />
          </div>
        )
      case 'TYPE_RADIO_VERTICAL':
        return (
          <RadioQuestion
            key={`type-radio-${question.id}`}
            title={question.question}
            id={question.id}
            onDataSelect={handleDataSelect}
            required={question.is_required}
            defaultValue={question.answer && question.answer.value}
            data={question.question_option && question.question_option.options}
          />
        )
      default:
        return null
    }
  }, [handleInputChange, handleDataSelect])

  const renderTheQuestion = useCallback((questions = []) => {
    // render the question on basis of type and data
    const questionsRenderMap = []
    that.current.isAllOptional = true
    that.current.requiredQuestionMap = {}
    for (let index = 0; index < questions.length; index++) {
      const question = questions[index]
      that.current.isAllOptional = that.current.isAllOptional && !question.is_required
      if (question.is_required) {
        // this the local map for the questions required
        that.current.requiredQuestionMap = {
          ...that.current.requiredQuestionMap,
          [question.id]: question.is_required
        }
      }
      questionsRenderMap.push(
        <Fragment key={`question-${question.id}`}>
          {questionBlock(question)}
          {
            ((index + 1) !== questions.length) && <div className='separator' />
          }
        </Fragment>
      )
    }
    return questionsRenderMap
  }, [questionBlock])

  return (
    <Container
      title={LANG_STRINGS.questionnaire}
      className='bg-white'
      hideBackButton
      hideBottomTabs
      loader={GET_QUESTION_STEPS_LOADER || GET_QUESTION_LOADER || SUBMIT_ANSWER_LOADER || GET_CITIES_LOADER}
    >
      <QuestionContainerStyle>
        {
          getQuestionData.questions && !GET_QUESTION_STEPS_ERROR && (
            <QuestionSteps
              current={that.current.step}
              stepData={getQuestionStepsData[that.current.step - 1]}
            />
          )
        }
        {
          getQuestionData.questions && !!getQuestionData.questions.length ? (
            <div className='container-body'>
              {renderTheQuestion(getQuestionData.questions)}
            </div>
          )
            : (
              (GET_QUESTION_LOADER === false) && (
                <EmptyList height='102px' content={ERROR_LANG.somethingWentWrong} />
              )
            )
        }
        {
          getQuestionData.questions && !!getQuestionData.questions.length && !GET_QUESTION_ERROR && (
            <BottomBtn
              showPrev={showPrev}
              completedLinePercent={completedPercent}
              onNextClick={handleNextClick}
              history={history}
              backBtnId={`questions-back-btn-${that.current.step}`}
              nextBtnId={`questions-next-btn-${that.current.step}`}
              nextBtnText={(that.current.step < 3) ? LANG_STRINGS.nextSmall : LANG_STRINGS.done}
              disabledNext={that.current.isAllOptional ? false : !isNextEnable}
            />
          )
        }
        {
          showBarMap.show && (
            <ShowSnackbar
              show={showBarMap.show}
              text={showBarMap.msg}
              error={showBarMap.error}
            />
          )
        }
      </QuestionContainerStyle>
    </Container>
  )
}

export default QuestionsContainer
