import { useState, useCallback, useRef, useMemo } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, InnerInput } from '../../../../../components'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import HorizontalRadioQuestion from '../HorizontalRadioQuestion'
import QuestionTitle from '../QuestionTitle'
import { CheckboxQuestionStyle } from './index.style'

function CheckboxQuestion (props) {
  const {
    title, data = [], onDataSelect,
    defaultValue = {}, required, resetChild
  } = props
  const preSelectedData = useMemo(() => {
    const checkedMap = {}
    for (const item of data) {
      if (defaultValue[item.title]) {
        checkedMap[item.title] = {
          checked: true,
          textValue: defaultValue[item.title],
          checkboxQuestions: item.questions
        }
      }
    }
    return checkedMap
  }, [defaultValue, data])
  const [checkedData, setCheckedData] = useState(preSelectedData || {})
  const localStore = useRef(defaultValue)

  const handleChangeCheckBox = useCallback((selectedQuestion) => {
    const { current = {} } = localStore
    const isChecked = checkedData[selectedQuestion.title] && checkedData[selectedQuestion.title].checked
    if (!isChecked) {
      localStore.current = {
        ...current,
        [selectedQuestion.title]: !isChecked
      }
      setCheckedData({
        ...checkedData,
        [selectedQuestion.title]: {
          checked: !isChecked,
          checkboxQuestions: selectedQuestion.questions
        }
      })
      onDataSelect({
        checked_value: {
          ...localStore.current
        }
      })
    } else {
      // remove the key if the value is unselected
      delete localStore.current[selectedQuestion.title]
      delete checkedData[selectedQuestion.title]
      // this will re-render the tree
      setCheckedData({ ...checkedData })
      const { questions = [] } = selectedQuestion
      const question = questions[0] || {}
      onDataSelect({
        checked_value: {
          ...localStore.current
        },
        removeId: question.id
      }, '', 'remove')
    }
  }, [checkedData, onDataSelect])

  const handleRadioChange = useCallback((selectedQuestion, scale, currentRadioItem) => {
    // handle checked data
    setCheckedData({
      ...checkedData,
      [selectedQuestion.title]: {
        ...(checkedData[selectedQuestion.title] || {}),
        scale
      }
    })
    onDataSelect({
      value: scale
    }, currentRadioItem)
  }, [onDataSelect, checkedData])

  const handleInputChange = useCallback((value, question) => {
    setCheckedData((checkedData) => {
      checkedData[question.title].textValue = value
      return {
        ...checkedData
      }
    })
    localStore.current = {
      ...localStore.current,
      [question.title]: value
    }
    onDataSelect({
      checked_value: {
        ...localStore.current
      }
    })
  }, [onDataSelect])

  return (
    <CheckboxQuestionStyle>
      {
        title && (
          <QuestionTitle title={title} required={required} />
        )
      }
      {
        data.map((question, index) => (
          <div className='checkbox-container' key={`checkbox-container-${index}`}>
            <Row align='center' key={`checkbox_question_${index}`}>
              <CustomCheckbox
                isChecked={checkedData[question.title] && checkedData[question.title].checked}
                onChange={() => handleChangeCheckBox(question)}
                name='checkbox'
                id='checkbox'
                color={AgentColorPallette.black}
              />
              {
                (question.title === 'Lainnya...') ? (
                  <InnerInput
                    name={question.title}
                    className='question-input-text'
                    placeholder='Lainnya...'
                    displayBorder
                    disabled={!checkedData[question.title]}
                    value={checkedData[question.title] ? checkedData[question.title].textValue : ''}
                    onChange={(e) => handleInputChange(e.target.value, question)}
                  />
                ) : (
                  <CustomText color={AgentColorPallette.black}>
                    {question.title}
                  </CustomText>
                )
              }
            </Row>
            {
              checkedData[question.title] && checkedData[question.title].checkboxQuestions && checkedData[question.title].checkboxQuestions.map(
                (item) => (
                  <HorizontalRadioQuestion
                    key={`horizontal-question_${question.title.replace(/\s/g, '')}`}
                    id={`horizontal-question_${question.title.replace(/\s/g, '')}`}
                    title={item.question}
                    selectedData={checkedData[question.title]}
                    data={item.question_option.options}
                    defaultValue={resetChild ? {} : item.answer}
                    onRadioSelect={(scale) => handleRadioChange(question, scale, item)}
                  />
                )
              )
            }
          </div>
        ))
      }
    </CheckboxQuestionStyle>
  )
}

export default CheckboxQuestion
