import { CustomText, InnerInput } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import BooleanQuestion from '../components/BooleanQuestion'
import CheckboxQuestion from '../components/CheckboxQuestion'
import HorizontalRadioQuestion from '../components/HorizontalRadioQuestion'

export const questionElements = (question, handlerFun) => {
  switch (question.question_type) {
    case 'TYPE_BOOLEAN':
      return (
        <BooleanQuestion
          key={`boolean-question-key-${question.id}`}
          title={question.question}
          data={question}
          onDataSelect={(value) => handlerFun(question, { answer: value })}
        />
      )
    case 'TYPE_TEXT':
      return (
        <div key={`text-question-key-${question.id}`}>
          <CustomText
            color={AgentColorPallette.black}
            weight={700}
            bottom='8px'
          >
            {question.question || question.question_header}
          </CustomText>
          <InnerInput
            name={`question_${question.id}`}
            className='question-input-text'
            placeholder='Masukan here'
            displayBorder
            onChange={(e) => handlerFun(question, { answer: e.target.value })}
          />
        </div>
      )
    case 'TYPE_RADIO_HORIZONTAL':
      return (
        <HorizontalRadioQuestion
          key={`horizontal-radio-key-${question.id}`}
          title={question.question}
          titleColor={AgentColorPallette.black}
          titleSize='12px'
          titleWeight={700}
          className='horizontal-radio-style'
          data={question.question_option && question.question_option.options}
          onRadioSelect={(data) => handlerFun(question, data)}
        />
      )
    case 'TYPE_CHECK_BOX':
      return (
        <CheckboxQuestion
          key={`checkbox-question-key-${question.id}`}
          title={question.question}
          id={question.id}
          resetChild={question.resetChild}
          defaultValue={question.resetChild ? {} : (question.answer && question.answer.checked_value)}
          data={question.question_option && question.question_option.options}
          required={question.is_required}
          onDataSelect={(selectedData, childQue, actionType) => handlerFun(childQue || question, selectedData, actionType)}
        />
      )
    default:
      return null
  }
}

export const getPercentageCal = (totalQuestions, totalFilled, totalPercent) => {
  return (totalPercent / totalQuestions) * totalFilled
}
