import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useQuestionnaireContextValue } from '../../context'
import { getQuestions, getQuestionsSteps, submitAnswers, updateRequiredQuestion } from '../actions'

export const useQuestionServiceCall = (actionsCall = () => {}) => {
  const [questionsState, dispatch] = useQuestionnaireContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [questionsState, request]
}

export const useGetQuestionsSteps = () => {
  return useQuestionServiceCall(getQuestionsSteps)
}

export const useGetQuestions = () => {
  return useQuestionServiceCall(getQuestions)
}

export const useSubmitAnswers = () => {
  return useQuestionServiceCall(submitAnswers)
}

export const useUpdateRequiredQuestion = () => {
  // this function required to maintain the map of required
  // questions id
  const [state, dispatch] = useQuestionnaireContextValue()
  const updateCall = (payload) => {
    dispatch(updateRequiredQuestion(payload))
  }
  return [state.requiredQuestionMap, updateCall]
}
