import { find } from 'lodash/collection'
import { useState, useCallback, useRef, useMemo, useEffect } from 'react'
import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { questionElements } from '../../helpers'
import QuestionTitle from '../QuestionTitle'
import { BooleanQuestionStyle } from './index.style'

function BooleanQuestion (props) {
  const {
    title, data = {}, onDataSelect,
    defaultValue, required, preData = {}
  } = props
  const questionOption = useMemo(
    () => data.question_option && data.question_option.options,
    [data.question_option]
  )
  const preQuestionsData = useMemo(() => {
    return find(questionOption, { title: defaultValue })
  }, [defaultValue, questionOption])

  const [selected, setSelected] = useState({
    value: defaultValue,
    questions: preQuestionsData && preQuestionsData.questions
  })
  const localStore = useRef({})
  useEffect(() => {
    if (preData[data.id] && preData[data.id].multiple_value) {
      localStore.current = {
        [data.id]: {
          value: preData[data.id].value
        },
        ...preData[data.id].multiple_value
      }
    }
  }, [preData, data.id])

  const handleValueSelect = ({ questions, title }) => {
    setSelected({
      ...selected,
      questions,
      resetChildQuestions: true,
      value: title
    })
    localStore.current = {
      [data.id]: {
        value: title
      }
    }
    onDataSelect(localStore.current)
  }

  const handleClick = useCallback((question, selectedData = {}, actionType) => {
    const { current } = localStore
    if (actionType === 'remove') {
      // here remove the corresponding keys from the list
      delete current[selectedData.removeId]
      delete selectedData.removeId
    }
    current[question.id] = {
      ...current[question.id],
      ...selectedData
    }
    onDataSelect({
      [data.id]: {
        multiple_value: {
          ...current
        }
      }
    })
  }, [onDataSelect, data.id])

  const renderChildQuestion = useCallback((questions, resetChild) => {
    const questionsMap = []
    for (const question of questions) {
      questionsMap.push(
        questionElements({ ...question, resetChild }, handleClick)
      )
    }
    return questionsMap
  }, [handleClick])

  return (
    <BooleanQuestionStyle>
      <QuestionTitle title={title} required={required} />
      <Row align='stretch'>
        <DisplayFlexCCC
          key='yes'
          className={`question-value question-left-value ${(selected.value === questionOption[0].title) && 'active'}`}
          onClick={() => handleValueSelect(questionOption[0])}
        >
          {questionOption[0] && questionOption[0].title}
        </DisplayFlexCCC>
        <div className={`value-separator ${selected.value && 'active-separator'}`} />
        <DisplayFlexCCC
          key='no'
          className={`question-value question-right-value ${(selected.value === questionOption[1].title) && 'active'}`}
          onClick={() => handleValueSelect(questionOption[1])}
        >
          {questionOption[1] && questionOption[1].title}
        </DisplayFlexCCC>
      </Row>
      {
        selected.questions && (
          <div className='question-options'>
            {renderChildQuestion(selected.questions, selected.resetChildQuestions)}
          </div>
        )
      }
    </BooleanQuestionStyle>
  )
}

export default BooleanQuestion
