import { DisplayFlexCCC, Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { QuestionStepsStyle } from './index.style'

function QuestionSteps (props) {
  const { current = 1, stepData = {} } = props
  return (
    <QuestionStepsStyle align='center' justify='space-between'>
      <div>
        <CustomText color={AgentColorPallette.black} size='16px' weight={800}>
          {stepData.step_name}
        </CustomText>
        <CustomText color={AgentColorPallette.fontDarkerGrey} size='10px'>
          {stepData.step_subheading}
        </CustomText>
      </div>
      <Row align='start' justify='space-between'>
        {
          [1, 2, 3].map((step) => {
            return (
              <DisplayFlexCCC
                className='steps-box'
                key={`steps_${step}`}
              >
                <div className={`steps-bullet ${current === step && 'steps-active'}`} />
                {
                  (current === step) && (
                    <CustomText color={AgentColorPallette.fontDarkerGrey} size='10px'>
                      {step}
                    </CustomText>
                  )
                }
              </DisplayFlexCCC>
            )
          })
        }
      </Row>
    </QuestionStepsStyle>
  )
}

export default QuestionSteps
