import { ConfigUrl } from '../../../../configs/url'

export const QUESTIONS_ACTIONS = {
  GET_QUESTION_STEPS_REQUEST: 'GET_QUESTION_STEPS_REQUEST',
  GET_QUESTION_STEPS: 'GET_QUESTION_STEPS',

  GET_QUESTION_REQUEST: 'GET_QUESTION_REQUEST',
  GET_QUESTION: 'GET_QUESTION',

  SUBMIT_ANSWER_REQUEST: 'SUBMIT_ANSWER_REQUEST',
  SUBMIT_ANSWER: 'SUBMIT_ANSWER',

  UPDATE_REQUIRED_QUESTIONS: 'UPDATE_REQUIRED_QUESTIONS'
}

export const getQuestionsSteps = (payload) => ({
  type: QUESTIONS_ACTIONS.GET_QUESTION_STEPS_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.getQuestionStepsApi
  }
})

export const getQuestions = (payload) => ({
  type: QUESTIONS_ACTIONS.GET_QUESTION_REQUEST,
  payload: {
    ...payload,
    method: 'get', // 'authGet',
    url: ConfigUrl.getQuestionsApi(payload.step)
  }
})

export const submitAnswers = (payload) => ({
  type: QUESTIONS_ACTIONS.SUBMIT_ANSWER_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.submitQuestionAnswersApi
  }
})

export const updateRequiredQuestion = (payload) => ({
  type: QUESTIONS_ACTIONS.UPDATE_REQUIRED_QUESTIONS,
  payload
})
