import { ConfigUrl } from '../../../configs/url'

export const SELECT_CITY_ACTIONS = {
  GET_CITIES_REQUEST: 'GET_CITIES_REQUEST',
  GET_CITIES: 'GET_CITIES'
}

// Change the City API
export const getCitiesRequest = (payload) => ({
  type: SELECT_CITY_ACTIONS.GET_CITIES_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getPropertyCities('all')
  }
})
