import { useCallback, useEffect, useRef } from 'react'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { LANG_STRINGS } from '../../../lang'
import AutoSearchModal from '../../AutoSearchModal'
import CustomText from '../../CustomText'
import { useGetCitiesData } from '../state/hooks/useSelectCityState'
import { SelectModalStyle } from './index.style'

function SelectCityModalContainer (props) {
  const { title, error, onDataSelect = () => {}, defaultValue } = props
  const [{ getCitiesData = [] }, getCitiesRequest] = useGetCitiesData()
  const prevProps = useRef({
    isCalledStart: false
  })
  const [{ GET_CITIES_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    if (GET_CITIES_LOADER === undefined || !prevProps.current.isCalledStart) {
      prevProps.current.isCalledStart = true
      getCitiesRequest()
    }
  }, [getCitiesRequest, GET_CITIES_LOADER, getCitiesData])

  const handleSelectAutoInput = useCallback((value) => {
    // handle the data
    if (onDataSelect) {
      onDataSelect(value)
    }
  }, [onDataSelect])

  return (
    <SelectModalStyle>
      <CustomText
        color={AgentColorPallette.black}
        weight={700}
        bottom='8px'
      >
        {title}
      </CustomText>
      <AutoSearchModal
        name='searchCity'
        errorField={error}
        placeholder={LANG_STRINGS.searchCity}
        title={LANG_STRINGS.searchCity}
        defaultValue={defaultValue}
        onSelect={handleSelectAutoInput}
        data={getCitiesData}
        loading={GET_CITIES_LOADER ? 'searchCity' : ''}
        className='search-city-container'
        dataKey='city_code'
        displayKey='city_name'
      />
    </SelectModalStyle>
  )
}

export default SelectCityModalContainer
